// one translation unit, no allocation, no virtual dispatch in the decision path
class Monitor final {
public:
    [[nodiscard]] Decision check(SubjectId s, Action a, ObjectId o) const noexcept {
        const Rule* r = table_.find({s, a, o});      // table_ is read-only, owned elsewhere
        return (r && r->allow) ? Decision::allow : Decision::deny;   // unknown => deny
    }
private:
    const RuleTable& table_;
};
// a capability only the monitor can mint, and it cannot be copied out
class ReadLedger { ReadLedger() = default; friend class Monitor; Ledger& ledger_; };
